def build():
    d = new("crypto", subtitle="Криптографические решения, модель угроз и границы гарантий")
    d.h1("ВВЕДЕНИЕ", numbered=False)
    d.p("Документ определяет криптографическую подсистему NEXO и модель угроз. Он нормативен для разработки клиентов и сервера: "
        "любое отклонение от описанных алгоритмов, параметров и процедур допускается только после изменения этого документа. Приведённые "
        "решения основаны на опубликованных стандартах и проверенных протоколах; собственные криптографические примитивы не разрабатываются.")
    d.note("Криптографическая подсистема не заменяет независимого аудита. Перед публичным запуском необходимо провести внешнюю проверку "
           "реализации (раздел {sec:verify}). Документ не является заключением о соответствии требованиям законодательства к средствам шифрования; "
           "вопросы правового режима шифровальных средств вынесены в " + ref("legalrisk") + ".")

    d.h1("ЦЕЛИ И ГРАНИЦЫ ГАРАНТИЙ", key="goals")
    d.h2("Цели защиты")
    d.numbered([
        "**Пароль никогда не покидает устройство** и не может быть получен из данных сервера;",
        "**Секретные чаты недоступны серверу** и любому, кто получил доступ к серверу, базе данных или резервным копиям;",
        "**Доступ к учётной записи** защищён от подбора, перехвата токенов и подмены устройств;",
        "**Локальные данные** на устройстве защищены при утрате или краже устройства;",
        "**Транспорт** защищён от прослушивания и подмены;",
        "**Минимизация данных**: система не запрашивает номер телефона и почту, журналы не содержат содержимого.",
    ], style="n")
    d.h2("Что система НЕ гарантирует", key="limits")
    d.p("Честное описание границ необходимо для корректных ожиданий пользователей и отражено в Пользовательском соглашении:")
    d.table("Границы гарантий", ["Область", "Ограничение"], [
        ["Обычные чаты", "Защищены шифрованием при передаче и на дисках сервера, но содержимое доступно серверной части (необходимо для синхронизации, поиска на сервере, модерации по жалобе). Это не сквозное шифрование."],
        ["Метаданные", "Сервер знает, кто с кем общается, когда и в каких объёмах, IP-адреса и устройства в ограниченные сроки. Скрыть метаданные от сервера система не может."],
        ["Звонки", "Аудио и видео идут через SFU и защищены только на участках клиент–SFU (DTLS-SRTP). Сквозного шифрования нет."],
        ["Веб-версия", "Секретные чаты недоступны. Клиентский код загружается с сервера, поэтому веб-клиент доверяет серверу в большей степени, чем установленные приложения."],
        ["Скомпрометированное устройство", "Вредоносная программа с правами пользователя читает данные так же, как приложение. Снимки экрана, копирование и пересылка остаются на усмотрение собеседника."],
        ["Потеря ключа восстановления и пароля", "Данные и доступ не восстанавливаются. Секретные чаты привязаны к устройству и при его утрате недоступны."],
        ["Автоудаление", "Сообщения удаляются у системы, но не у человека, успевшего их сохранить."],
        ["Первый контакт в секретном чате", "До сверки номера безопасности нельзя исключить подмену ключей сервером; клиент показывает статус проверки."],
    ], widths=[3.7, 10.8], key="limits", font=11)

