        ["Ключ восстановления", "Восстановление доступа", "У пользователя; на сервере – проверочное значение"],
        ["Ключи устройств и секретных чатов", "Конфиденциальность секретной переписки", "Только устройство"],
        ["Содержимое обычных чатов и файлов", "Конфиденциальность", "БД и хранилище сервера; локальная БД клиентов"],
        ["Метаданные", "Приватность связей", "БД и журналы сервера"],
